 24	/** Parse a JSON-RPC response that may arrive as plain JSON or an SSE `data:` frame. */
 25	function parseRpc(text: string): JsonRpcResponse | null {
 26	  const t = text.trim();
 27	  if (t.startsWith("{")) {
 28	    try {
 29	      return JSON.parse(t) as JsonRpcResponse;
 30	    } catch {
 31	      return null;
 32	    }
 33	  }
 34	  for (const line of t.split("\n")) {
 35	    const l = line.trim();
 36	    if (l.startsWith("data:")) {
 37	      try {
 38	        return JSON.parse(l.slice(5).trim()) as JsonRpcResponse;
 39	      } catch {
 40	        /* keep scanning */
 41	      }
 42	    }
 43	  }
 44	  return null;
 45	}
