 47	interface PostResult {
 48	  ok: boolean;
 49	  status: number;
 50	  json: JsonRpcResponse | null;
 51	  sessionId: string | undefined;
 52	}
 53	
 54	async function post(url: string, token: string, body: unknown, sessionId?: string): Promise<PostResult> {
 55	  const headers: Record<string, string> = {
 56	    "Content-Type": "application/json",
 57	    Accept: "application/json, text/event-stream",
 58	  };
 59	  if (token) headers["Authorization"] = `Bearer ${token}`;
 60	  if (sessionId) headers["Mcp-Session-Id"] = sessionId;
 61	  const res = await fetch(url, {
 62	    method: "POST",
 63	    headers,
 64	    body: JSON.stringify(body),
 65	    redirect: "manual",
 66	    signal: AbortSignal.timeout(12_000),
 67	  });
 68	  const newSession = res.headers.get("Mcp-Session-Id") ?? sessionId;
 69	  let json: JsonRpcResponse | null = null;
 70	  if (res.ok) json = parseRpc(await res.text());
 71	  return { ok: res.ok, status: res.status, json, sessionId: newSession };
 72	}
