 81	/** Connect, run the initialize handshake, and list the server's tools. */
 82	export async function connectAndListTools(url: string, token: string): Promise<McpConnectResult> {
 83	  const init = await post(url, token, {
 84	    jsonrpc: "2.0",
 85	    id: 1,
 86	    method: "initialize",
 87	    params: { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: "aria-sourcing", version: "1.0" } },
 88	  });
 89	  if (!init.ok) return { ok: false, error: `MCP server responded ${init.status}.` };
 90	  if (!init.json?.result) return { ok: false, error: init.json?.error?.message ?? "No valid MCP initialize response." };
 91	
 92	  const serverName = init.json.result.serverInfo?.name ?? "MCP server";
 93	  const session = init.sessionId;
 94	
 95	  // Acknowledge initialization (best-effort; some servers require it before tools/list).
 96	  try {
 97	    await post(url, token, { jsonrpc: "2.0", method: "notifications/initialized" }, session);
 98	  } catch {
 99	    /* ignore — not all servers need this */
100	  }
101	
102	  // List tools (best-effort: a server may not expose tools).
103	  let tools: McpTool[] = [];
104	  try {
105	    const list = await post(url, token, { jsonrpc: "2.0", id: 2, method: "tools/list", params: {} }, session);
106	    tools = (list.json?.result?.tools ?? []).map((t) => ({
107	      name: t.name,
108	      description: t.description,
109	      inputSchema: t.inputSchema,
110	    }));
111	  } catch {
112	    /* tools optional */
113	  }
114	
115	  return { ok: true, serverName, tools };
116	}
