118	/** Call a single tool on the server. Returns the tool result content or an error. */
119	export async function callMcpTool(
120	  url: string,
121	  token: string,
122	  toolName: string,
123	  args: Record<string, unknown>,
124	): Promise<{ ok: boolean; content?: unknown; error?: string }> {
125	  const init = await post(url, token, {
126	    jsonrpc: "2.0",
127	    id: 1,
128	    method: "initialize",
129	    params: { protocolVersion: PROTOCOL_VERSION, capabilities: {}, clientInfo: { name: "aria-sourcing", version: "1.0" } },
130	  });
131	  if (!init.ok || !init.json?.result) return { ok: false, error: init.json?.error?.message ?? "MCP initialize failed." };
132	  const session = init.sessionId;
133	  try {
134	    await post(url, token, { jsonrpc: "2.0", method: "notifications/initialized" }, session);
135	  } catch {
136	    /* ignore */
137	  }
138	  const call = await post(
139	    url,
140	    token,
141	    { jsonrpc: "2.0", id: 2, method: "tools/call", params: { name: toolName, arguments: args } },
142	    session,
143	  );
144	  if (!call.json?.result) return { ok: false, error: call.json?.error?.message ?? "Tool call returned no result." };
145	  return { ok: !call.json.result.isError, content: call.json.result.content };
146	}

