101	function logUpstream(level: "info" | "error", message: string, meta?: Record<string, unknown>) {
102	  // Structured log line for production observability. In Vercel this becomes
103	  // a regular function log; in self-hosted environments it can be scraped.
104	  // Redact before emitting: mask sensitive-keyed values, then scrub any emails /
105	  // credentials that leaked into free-text fields (e.g. upstream error bodies,
106	  // network error messages) so nothing sensitive reaches a log sink.
107	  const entry = { time: new Date().toISOString(), source: "hermes-proxy", level, message, ...redactObject(meta ?? {}) };
108	  const line = redactSecrets(redactEmail(JSON.stringify(entry)));
109	  if (level === "error") {
110	    console.error(line);
111	  } else {
112	    console.log(line);
113	  }
114	}
