121	/**
122	 * Resolve the caller's enabled MCP servers into connectable servers with their tools.
123	 * The bearer token for each is resolved from the vault server-side (never from the
124	 * browser). http(s) only (SSRF). Servers that fail to connect or expose no tools are
125	 * skipped, so a broken server can't block the chat.
126	 */
127	async function gatherMcpServers(
128	  servers: { url: string; apiKeyId?: string }[],
129	): Promise<ResolvedMcpServer[]> {
130	  const resolved: ResolvedMcpServer[] = [];
131	  for (const s of servers) {
132	    let parsed: URL;
133	    try {
134	      parsed = new URL(s.url);
135	    } catch {
136	      continue;
137	    }
138	    if (parsed.protocol !== "https:" && parsed.protocol !== "http:") continue;
139	    // SSRF guard: block private/loopback/link-local/metadata hosts (and DNS-rebinding)
140	    // before the server ever dials the caller-supplied URL. This server is reused for
141	    // every tool call the model makes during the loop, so this is a repeatable channel
142	    // — not just a one-shot probe.
143	    const guard = await assertPublicUrl(s.url);
144	    if (!guard.ok) continue;
145	    const token = s.apiKeyId ? await resolveVaultSecret(s.apiKeyId) : "";
146	    const conn = await connectAndListTools(s.url, token);
147	    if (conn.ok && conn.tools && conn.tools.length) {
148	      resolved.push({ url: s.url, token, tools: conn.tools });
149	    }
150	  }
151	  return resolved;
152	}
