  1	/* ============================================================================
  2	   Log redaction — scrub PII / secrets before anything reaches a log sink.
  3	
  4	   Audit finding: candidate emails and raw provider request/response bodies were
  5	   logged in cleartext (e.g. the Aria proxy log lines and provider error text).
  6	   These helpers are dependency-free (standard lib / Web APIs only) and never
  7	   throw — a logging utility that throws is worse than one that over-redacts.
  8	
  9	   - redactEmail   : mask the local part of every email in a string  -> a***@domain.com
 10	   - redactSecrets : mask bearer tokens, sk-/provider keys, JWTs, long hex/base64
 11	   - redactObject  : shallow-clone an object, masking values of sensitive keys
 12	   - safeLog       : console.log wrapper that deep-redacts strings and objects
 13	   ========================================================================== */
 14	
 15	/** Keys whose values are assumed sensitive wherever they appear. */
 16	const SENSITIVE_KEY = /(email|token|secret|key|authorization|password|apikey)/i;
 17	
 18	/** Email matcher. Used only with String.replace (which resets lastIndex), so the
 19	    global flag is safe here; never call .test() on this instance. */
 20	const EMAIL_RE = /([A-Za-z0-9._%+-])[A-Za-z0-9._%+-]*@([A-Za-z0-9.-]+\.[A-Za-z]{2,})/g;
 21	
 22	/**
 23	 * Mask the local part of every email address found in `s`, keeping the first
 24	 * character and the full domain so log lines stay greppable by domain.
 25	 *   "jane.doe@acme.com" -> "j***@acme.com"
 26	 */
 27	export function redactEmail(s: string): string {
 28	  if (typeof s !== "string") return s;
 29	  return s.replace(EMAIL_RE, (_m, first: string, domain: string) => `${first}***@${domain}`);
 30	}
 31	
 32	/**
 33	 * Mask common credential shapes in free text: Authorization schemes, JWTs,
 34	 * provider API keys with a known prefix, AWS access-key ids, and long
 35	 * hex / base64 secrets. Over-redacts by design — false positives are harmless
 36	 * in a log line, leaked secrets are not.
 37	 */
 38	export function redactSecrets(s: string): string {
 39	  if (typeof s !== "string") return s;
 40	  return s
 41	    // Authorization schemes: keep the scheme, drop the credential.
 42	    .replace(/\b(Bearer|Basic|Token)\s+[A-Za-z0-9\-._~+/]+=*/gi, "$1 ***")
 43	    // JWTs (header.payload.signature; base64url header always begins with eyJ).
 44	    .replace(/\beyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, "***")
 45	    // Provider API keys with a known prefix (OpenAI/Anthropic sk-, Groq gsk_,
 46	    // xAI xai-, Slack xoxb-, GitHub ghp_/github_pat_, …).
 47	    .replace(/\b(sk|pk|rk|gsk|xai|xoxb|xoxp|ghp|ghs|gho|github_pat)[-_][A-Za-z0-9\-_]{6,}/gi, "$1-***")
 48	    // AWS access-key ids.
 49	    .replace(/\b(?:AKIA|ASIA)[A-Z0-9]{12,}/g, "***")
 50	    // Long hex secrets (md5/sha/hmac/api hashes).
 51	    .replace(/\b[0-9a-f]{32,}\b/gi, "***")
 52	    // Long base64 / base64url secrets.
 53	    .replace(/\b[A-Za-z0-9+/]{40,}={0,2}/g, "***");
 54	}
