 56	/** Redact a single string through both passes. */
 57	function redactString(s: string): string {
 58	  return redactSecrets(redactEmail(s));
 59	}
 60	
 61	/** Mask the value of a sensitive key. Emails keep their shape; everything else
 62	    collapses to a fixed marker so no fragment of a secret survives. */
 63	function maskValue(v: unknown): string {
 64	  if (typeof v === "string" && v.includes("@")) return redactEmail(v);
 65	  return "***";
 66	}
 67	
 68	/**
 69	 * Return a shallow clone of `o` with the values of any key matching
 70	 * SENSITIVE_KEY masked. Shallow by contract — nested objects are not traversed
 71	 * (use safeLog for deep redaction). Non-objects are returned unchanged.
 72	 */
 73	export function redactObject<T>(o: T): T {
 74	  if (o === null || typeof o !== "object") return o;
 75	  if (Array.isArray(o)) return [...o] as unknown as T;
 76	  const clone: Record<string, unknown> = { ...(o as Record<string, unknown>) };
 77	  for (const key of Object.keys(clone)) {
 78	    if (SENSITIVE_KEY.test(key)) clone[key] = maskValue(clone[key]);
 79	  }
 80	  return clone as T;
 81	}
 82	
 83	/** Deep-redact an arbitrary value: scrub strings, mask sensitive keys, recurse
 84	    into arrays/objects. `seen` guards against circular references. */
 85	function deepRedact(v: unknown, seen: WeakSet<object>): unknown {
 86	  if (typeof v === "string") return redactString(v);
 87	  if (v === null || typeof v !== "object") return v;
 88	  if (seen.has(v)) return "[Circular]";
 89	  seen.add(v);
 90	  if (Array.isArray(v)) return v.map((item) => deepRedact(item, seen));
 91	  const out: Record<string, unknown> = {};
 92	  for (const [key, val] of Object.entries(v as Record<string, unknown>)) {
 93	    out[key] = SENSITIVE_KEY.test(key) ? maskValue(val) : deepRedact(val, seen);
 94	  }
 95	  return out;
 96	}
