 98	/**
 99	 * console.log wrapper that redacts before emitting. String arguments are scrubbed
100	 * for emails and secrets; objects are deep-redacted (sensitive-key values masked,
101	 * string values scrubbed) and stringified to JSON; other primitives pass through.
102	 * Never throws — unserializable values degrade to a marker.
103	 */
104	export function safeLog(...args: unknown[]): void {
105	  const out = args.map((arg) => {
106	    if (typeof arg === "string") return redactString(arg);
107	    if (arg !== null && typeof arg === "object") {
108	      try {
109	        return JSON.stringify(deepRedact(arg, new WeakSet()));
110	      } catch {
111	        return "[unserializable]";
112	      }
113	    }
114	    return arg;
115	  });
116	  console.log(...out);
117	}
